    motsCles: ['bash', 'script', 'if', 'then', 'else', 'case', 'test', 'condition', 'chmod +x'],
    params: [{ id: 'script', label: 'nom du script', type: 'arg', exemple: 'condition.sh', aide: 'Créé dans le dossier courant ; remplace un fichier du même nom.' }],
    privileges: 'Utilisateur ordinaire.',
    etapes: [
      mod('Écrire le script', 'Le bloc « <<\'EOF\' » écrit les lignes suivantes dans le fichier, telles quelles (les guillemets autour de EOF empêchent le shell d’interpréter les $).', [
        sh('cat > {{script}} <<\'EOF\''),
        sh('#!/bin/bash'),
        sh('if [ -f "$1" ]; then'),
        sh('  echo "$1 est un fichier"'),
        sh('elif [ -d "$1" ]; then'),
        sh('  echo "$1 est un dossier"'),
        sh('else'),
        sh('  echo "$1 est introuvable"'),
        sh('fi'),
        sh('case "$2" in'),
        sh('  oui|o) echo "réponse positive" ;;'),
        sh('  non|n) echo "réponse négative" ;;'),
        sh('  *) echo "réponse inconnue" ;;'),
        sh('esac'),
        sh('EOF'),
      ], 'Aucun message : le fichier est créé.', { important: 'Si le script existait déjà, il est remplacé.' }),
      mod('Le rendre exécutable', 'chmod +x ajoute le droit d’exécution : sans lui, « ./script » répond « Permission non accordée ».', [sh('chmod +x {{script}}')], 'Aucun message.'),
      lec('L’exécuter', 'Deux arguments : $1 est le chemin à tester, $2 la réponse pour le case.', [sh('./{{script}} /etc/passwd oui'), sh('./{{script}} /tmp n'), sh('./{{script}} /rien x')], 'Trois sorties : « est un fichier / réponse positive », « est un dossier / réponse négative », « est introuvable / réponse inconnue ».', { verification: true }),
    ],
    verification: ['Les trois exécutions affichent les trois cas attendus.'],
